function interiorSignature(room,index){
 const common=new Room(room.variant);shell(common,index);const excluded=new Set();
 for(let height=0;height<room.height;height++)for(let depth=0;depth<room.depth;depth++)for(let width=0;width<room.width;width++)if(width===0||depth===0||width===room.width-1||depth===room.depth-1||height<room.floor||height===room.height-1||common.get(width,height,depth)!=='air'||(room.variant.key.startsWith('stairs/')&&height===17&&room.get(width,height,depth)==='smooth_sandstone'))excluded.add(room.index(width,height,depth));
 for(const port of room.variant.ports)for(const[width,height,depth]of port.cells)for(let inward=0;inward<=3;inward++)for(let offset=-1;offset<5;offset++){const target=[width,height+offset,depth];if(width===0)target[0]+=inward;else if(width===room.width-1)target[0]-=inward;else if(depth===0)target[2]+=inward;else target[2]-=inward;excluded.add(room.index(...target));}
 const raw=new Set(),normalized=new Set(),footprint=new Set(),layers={};
 for(let height=room.floor;height<room.height-1;height++)for(let depth=1;depth<room.depth-1;depth++)for(let width=1;width<room.width-1;width++){if(excluded.has(room.index(width,height,depth))||room.get(width,height,depth)==='air')continue;raw.add([width,height,depth].join(','));const coordinate=[Math.min(15,Math.floor((width-1)*16/(room.width-2))),Math.min(15,Math.floor((height-room.floor)*16/(room.height-1-room.floor))),Math.min(15,Math.floor((depth-1)*16/(room.depth-2)))];normalized.add(coordinate.join(','));if(height<room.floor+6)footprint.add([coordinate[0],coordinate[2]].join(','));layers[height]=(layers[height]??0)+1;}
 return{raw,normalized,footprint,excluded,layers};
}
function jaccard(first,last){let intersection=0;for(const point of first)if(last.has(point))intersection++;const union=first.size+last.size-intersection;return{intersection,union,similarity:union?intersection/union:1};}
function auditRooms(rooms,reports){
 const signatures=rooms.map(interiorSignature),pairs=[];
 const family=key=>key.startsWith('stairs/')?'stairs':key.includes('/layout/')?'child':key.startsWith('spawn/')?'spawn':key==='boss/eclipse_keeper'?'boss':key.startsWith('terminal/')?'terminal':key.startsWith('straight/room_')||['straight/hole','straight/platform'].includes(key)||key.startsWith('turn/')?'combat':'corridor';
 for(let first=0;first<rooms.length;first++)for(let last=first+1;last<rooms.length;last++){const sameSize=rooms[first].variant.size.join(',')===rooms[last].variant.size.join(','),sameFamily=family(rooms[first].variant.key)===family(rooms[last].variant.key);if(!sameSize&&!sameFamily)continue;const exact=jaccard(signatures[first].raw,signatures[last].raw),normalized=jaccard(signatures[first].normalized,signatures[last].normalized),layout=jaccard(signatures[first].footprint,signatures[last].footprint),similarity=sameSize?exact.similarity:normalized.similarity;const fixedStairs=sameFamily&&family(rooms[first].variant.key)==='stairs';const decision=similarity>=.9?(fixedStairs?'reviewed-fixed-steps':'must-rebuild'):'distinct';pairs.push({first:rooms[first].variant.key,last:rooms[last].variant.key,sameSize,sameFamily,solidAirJaccard:sameSize?exact.similarity:null,normalizedJaccard:normalized.similarity,lowLevelFootprintJaccard:layout.similarity,intersection:exact.intersection,union:exact.union,score:similarity,decision,explanation:fixedStairs?'Mandatory 16-block ascent uses actual three-wide sandstone stairs; independent shaft ledges / rotated flight / inscribed pier distinguish rooms.':similarity>=.9?'Non-corridor internal occupancy too similar: must rebuild.':'Interior occupancy differs after common shell/floor/port removal; footprint and vertical layer signatures reported separately.'});}
 pairs.sort((first,last)=>last.score-first.score);
 const repetition={schema:1,style:'fteclipsegen:desert',status:pairs.some(pair=>pair.decision==='must-rebuild')?'requires-rebuild':'passed',threshold:.9,exclusionRules:['All exterior boundary cells and base floor y<feet','Exact generated common shell/vault coordinates, independently reconstructed before room-specific architecture','Port width cells inward 0..3 and port y-1..y+4','Mandatory upper storey y17 smooth-sandstone deck in stairs; actual stair blocks retained'],normalization:'16x16x16 interior bins; solid-only Jaccard excludes shared air; low-level footprint projects first six interior heights',comparablePairs:pairs.length,rooms:rooms.map((room,index)=>({key:room.variant.key,family:family(room.variant.key),internalSolidCells:signatures[index].raw.size,excludedCells:signatures[index].excluded.size,normalizedSignatureSha256:hash(Buffer.from([...signatures[index].normalized].sort().join(';'))),rawSignatureSha256:hash(Buffer.from([...signatures[index].raw].sort().join(';'))),footprintSignatureSha256:hash(Buffer.from([...signatures[index].footprint].sort().join(';'))),verticalLayers:signatures[index].layers,baseline:reports[index].geometry})),highestPairs:pairs.slice(0,20),highSimilarityPairs:pairs.filter(pair=>pair.score>=.9),allPairs:pairs,repairs:[{key:'stairs/centered',change:'Original draft reused north-origin flight; rotate entire independent staircase 180 degrees for south-origin circulation.'},{key:'stairs/hole',change:'Move second flight west one block and widen Y12 branch to three blocks; distinguish shaft gallery.'},{key:'stairs/spiral',change:'Widen Y6 branch to three blocks; keep actual inscribed pier and branched lower galleries.'}]};
 save(join(output,'repetition-audit.json'),json(repetition));
 const styleResults=rooms.map((room,index)=>{
  const materials={},internalMaterials={};for(const state of room.blocks){const name=state.split('[')[0];materials[name]=(materials[name]??0)+1;}
  for(const coordinate of signatures[index].raw){const position=coordinate.split(',').map(Number),name=room.get(...position).split('[')[0];internalMaterials[name]=(internalMaterials[name]??0)+1;}
  const landmarks=landmarkBoxes[room.variant.key].map(([minimum,maximum,material])=>{const matches=[];for(let height=minimum[1];height<=maximum[1];height++)for(let depth=minimum[2];depth<=maximum[2];depth++)for(let width=minimum[0];width<=maximum[0];width++)if(room.get(width,height,depth).split('[')[0]===material)matches.push([width,height,depth]);return{requestedBox:{minimum,maximum},material:'minecraft:'+material,matchingBlocks:matches.length,actualBoundingBox:matches.length?{minimum:[0,1,2].map(axis=>Math.min(...matches.map(point=>point[axis]))),maximum:[0,1,2].map(axis=>Math.max(...matches.map(point=>point[axis])))}:null,passed:matches.length>=2};});
  const corners=[[2,2],[room.width-3,2],[2,room.depth-3],[room.width-3,room.depth-3]].map(([width,depth])=>{let run=0;for(let height=room.floor;height<Math.min(room.height-2,room.floor+7);height++)if(room.get(width,height,depth)!=='air')run++;return{position:[width,depth],solidHeightCells:run};});
  const fourCorners=corners.every(corner=>corner.solidHeightCells>=6);let centerSolid=0,centerTotal=0;for(let height=room.floor;height<Math.min(room.floor+5,room.height-1);height++)for(let depth=Math.floor(room.depth*.3);depth<room.depth*.7;depth++)for(let width=Math.floor(room.width*.3);width<room.width*.7;width++){centerTotal++;if(room.get(width,height,depth)!=='air')centerSolid++;}
  const sandstone=Object.entries(internalMaterials).filter(([name])=>name.includes('sandstone')).reduce((sum,[,count])=>sum+count,0);
  const passed=landmarks.every(landmark=>landmark.passed)&&sandstone>0&&reports[index].geometry.interiorChangedSolidAir>=70;
  return{key:room.variant.key,nbtSha256:reports[index].sha256,status:passed?'passed':'requires-rebuild',actualMaterials:materials,internalMaterials,landmarks,styleEvidence:{sandstoneInteriorBlocks:sandstone,actualLandmarksVerified:landmarks.filter(landmark=>landmark.passed).length,functionalForm:designs.get(room.variant.key).circulation,formReason:'The listed non-air material groups were measured inside final decoded NBT at recorded bounds; geometry and layers are checked separately from palette.'},risks:{recolorOnly:{detected:reports[index].geometry.interiorChangedSolidAir<70,interiorSolidAirChanges:reports[index].geometry.interiorChangedSolidAir},fourCornerColumnsAndEmptyHall:{cornerRuns:corners,centerSolidRatio:centerSolid/centerTotal,detected:fourCorners&&centerSolid/centerTotal<.03,decision:fourCorners?'Review actual ledger walls/pylons; four-corner scalar alone does not classify architecture.':'No four-tall-corner-pillar layout detected.'},repeatedCentralSymbol:{goldBlocks:materials.gold_block??0,decision:room.variant.key==='boss/eclipse_keeper'?'Gold annulus is suspended at Y15; center at feet level remains clear.':'Measured landmarks are walls, benches, columns, ledges or terminals rather than repeated central altar.'}},baselineGeometry:reports[index].geometry,decision:passed?'retain: verified physical landmarks and changed internal occupancy':'rebuild: material/landmark geometry absent'};
 });
 const centerGroups=new Map();for(const[index,result]of styleResults.entries()){const room=rooms[index],centerCells=[...signatures[index].raw].map(value=>value.split(',').map(Number)).filter(position=>position[1]<room.floor+5&&position[0]>=room.width*.3&&position[0]<=room.width*.7&&position[2]>=room.depth*.3&&position[2]<=room.depth*.7),signature=hash(Buffer.from(centerCells.map(position=>[position[0]-Math.floor(room.width/2),position[1]-room.floor,position[2]-Math.floor(room.depth/2)].join(',')).sort().join(';')));result.risks.repeatedCentralSymbol.actualLowCenterSolidCells=centerCells.length;result.risks.repeatedCentralSymbol.geometrySignatureSha256=signature;if(centerCells.length>=8){const group=centerGroups.get(signature)??[];group.push(result.key);centerGroups.set(signature,group);}}
 const repeatedCenterGroups=[...centerGroups.entries()].filter(([,keys])=>keys.length>1).map(([signature,keys])=>({signature,keys,decision:'must-review'}));assert.equal(repeatedCenterGroups.length,0,'Repeated nonempty center symbol');
 const style={schema:1,style:'fteclipsegen:desert',status:styleResults.every(result=>result.status==='passed')?'passed':'requires-rebuild',method:'Count actual bare IDs in decoded final NBT; inspect explicit architecture bounds; compare internal solid/air baseline; test corner runs and center occupation',centralSymbolCheck:{rule:'Material-independent relative occupancy signature of nonempty low central 40% footprint, first five heights, after common removal; minimum8 solid cells',repeatedCenterGroups},results:styleResults};save(join(output,'style-audit.json'),json(style));
 return{repetition,style};
}
