   save(join(output,relative),svg);const record={id:room.variant.key+'/'+direction.name,key:room.variant.key,direction:direction.name,cameraXZ:direction.camera,screenRightXZ:direction.screen,lookDirectionXZ:direction.camera.map(value=>-value),nbtSha256:reports[index].sha256,svgSha256:hash(Buffer.from(svg)),file:relative,renderedAtoms:atoms.length,polygonCount:polygons.length};views.push(record);
